    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    # Use 5 beams with moderate dimensions and density to balance mass and responsiveness
    for (xx, yy) in [(4.8, 2.6), (4.9, 2.6), (5.0, 2.6), (5.1, 2.6), (5.0, 2.7)]:
        b = sandbox.add_beam(xx, yy, 0.16, 0.32, angle=0, density=10.0)
        sandbox.add_joint(cabin, b, (xx, yy), type="rigid")
        beams.append(b)
