def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    x, y = pos
    vel = sandbox.get_vehicle_velocity()
    vx, vy = vel

    # Apply forces to maintain speed through critical zones
    if 5.5 <= x <= 7.5:
        # Counteract mud zone resistance with moderate forward force
        sandbox.apply_force(agent_body, (500.0, 0.0))
    elif 8.0 <= x <= 9.0:
        # Maximize speed boost in first impulse zone
        sandbox.apply_force(agent_body, (1000.0, 0.0))
    elif 9.5 <= x <= 11.0:
        # Control speed in decel zone to meet checkpoint requirements
        if vx > 2.8:  # Apply backward force if moving too fast (target upper bound is 2.7)
            sandbox.apply_force(agent_body, (-200.0, 0.0))
